CREATE TABLE "local_credentials" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "password_hash" character varying NOT NULL, "failed_attempts" bigint NOT NULL DEFAULT 0, "locked_until" timestamptz NULL, "password_changed_at" timestamptz NOT NULL, "must_change" boolean NOT NULL DEFAULT false, "user_local_credential" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "local_credentials_users_local_credential" FOREIGN KEY ("user_local_credential") REFERENCES "users" ("id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "local_credentials_user_local_credential_key" ON "local_credentials" ("user_local_credential");
